CREATE TABLE grammar_topics (
    id text PRIMARY KEY,
    slug text NOT NULL UNIQUE,
    title text NOT NULL,
    summary text NOT NULL,
    level text NOT NULL,
    icon text NOT NULL DEFAULT '✦',
    position integer NOT NULL DEFAULT 0,
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
    lesson jsonb NOT NULL DEFAULT '[]'::jsonb,
    practice jsonb NOT NULL DEFAULT '[]'::jsonb,
    game jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE user_grammar_progress (
    user_id bigint NOT NULL REFERENCES users(telegram_id) ON DELETE CASCADE,
    topic_id text NOT NULL REFERENCES grammar_topics(id) ON DELETE CASCADE,
    status text NOT NULL DEFAULT 'learning' CHECK (status IN ('learning', 'review')),
    best_score integer NOT NULL DEFAULT 0 CHECK (best_score BETWEEN 0 AND 100),
    interval_days integer NOT NULL DEFAULT 0,
    ease_factor numeric(4,2) NOT NULL DEFAULT 2.30,
    repetitions integer NOT NULL DEFAULT 0,
    due_date date NOT NULL,
    last_reviewed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, topic_id)
);

CREATE INDEX user_grammar_due_idx ON user_grammar_progress(user_id, due_date);

CREATE TABLE grammar_review_logs (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id bigint NOT NULL REFERENCES users(telegram_id) ON DELETE CASCADE,
    topic_id text NOT NULL REFERENCES grammar_topics(id) ON DELETE CASCADE,
    score integer NOT NULL,
    correct_count integer NOT NULL,
    question_count integer NOT NULL,
    next_interval integer NOT NULL,
    reviewed_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO grammar_topics (id, slug, title, summary, level, icon, position, status, lesson, practice, game) VALUES
(
  'grammar_gender_number', 'rod-i-chislo', 'Род и число',
  'Род существительных и образование множественного числа', 'A1', '◒', 1, 'published',
  $json$[
    {"title":"Три рода","text":"Мужской род обычно оканчивается на согласную или -й, женский — на -а/-я, средний — на -о/-е. Мягкий знак сам по себе род не показывает: словарь поможет запомнить ночь (ж.р.) и день (м.р.).","examples":["новый стол · новый музей","новая книга · новая неделя","новое окно · новое море"],"note":"Профессии на -тель обычно мужского рода: учитель, писатель."},
    {"title":"Множественное число","text":"Чаще всего добавляем -ы/-и. После г, к, х, ж, ч, ш, щ пишем -и. У слов на -о/-е обычно появляются -а/-я.","examples":["книга → книги · урок → уроки","окно → окна · море → моря","стул → стулья · друг → друзья"],"note":"Запомните частые особые формы: человек → люди, ребёнок → дети."},
    {"title":"Согласование","text":"Прилагательное и глагол прошедшего времени согласуются с существительным.","examples":["новая книга лежала","новые книги лежали"],"note":"Сначала найдите главное существительное, затем выбирайте окончание."}
  ]$json$::jsonb,
  $json$[
    {"id":"gn-p1","prompt":"Выберите правильный вариант","phrase":"Это ___ окно.","options":["новый","новая","новое"],"answer":"новое","explanation":"Окно — средний род, поэтому новое."},
    {"id":"gn-p2","prompt":"Образуйте множественное число","phrase":"урок → ?","options":["урокы","уроки","урока"],"answer":"уроки","explanation":"После к пишется -и."},
    {"id":"gn-p3","prompt":"Найдите особую форму","phrase":"ребёнок → ?","options":["ребёнки","ребята","дети"],"answer":"дети","explanation":"Ребёнок → дети — нерегулярная форма."}
  ]$json$::jsonb,
  $json$[
    {"id":"gn-g1","prompt":"Соберите пару","phrase":"интересн__ музей","options":["ый","ая","ое"],"answer":"ый","explanation":"Музей — мужской род."},
    {"id":"gn-g2","prompt":"Откройте ворота","phrase":"пять красивых ___","options":["окны","окон","окна"],"answer":"окон","explanation":"После пяти нужен родительный множественного числа: окон."},
    {"id":"gn-g3","prompt":"Выберите форму","phrase":"Мои друзья вчера ___.","options":["пришёл","пришла","пришли"],"answer":"пришли","explanation":"Во множественном числе — пришли."},
    {"id":"gn-g4","prompt":"Найдите исключение","phrase":"человек → ?","options":["человеки","люди","человека"],"answer":"люди","explanation":"Человек → люди."}
  ]$json$::jsonb
),
(
  'grammar_present', 'nastoyashchee-vremya', 'Настоящее время',
  'I и II спряжение, личные окончания и частые исключения', 'A1–A2', '↻', 2, 'published',
  $json$[
    {"title":"Как спрягать","text":"У глагола убираем -ть и меняем окончание по лицу. I спряжение: -у/-ю, -ешь, -ет, -ем, -ете, -ут/-ют. II спряжение: -у/-ю, -ишь, -ит, -им, -ите, -ат/-ят.","examples":["читать: читаю, читаешь, читает","говорить: говорю, говоришь, говорит"],"note":"Не определяйте спряжение только по одной форме — проверяйте инфинитив и исключения."},
    {"title":"II спряжение","text":"Ко II спряжению относятся почти все глаголы на -ить, кроме брить и стелить, а также 11 исключений.","examples":["видеть, смотреть, ненавидеть, зависеть, терпеть, обидеть, вертеть","слышать, дышать, держать, гнать"],"note":"Хотеть, бежать, есть и дать имеют особое спряжение."},
    {"title":"Чередования","text":"В форме я у некоторых глаголов меняется согласная.","examples":["писать → пишу · искать → ищу","любить → люблю · платить → плачу"],"note":"Эти формы лучше запоминать вместе с инфинитивом."}
  ]$json$::jsonb,
  $json$[
    {"id":"pr-p1","prompt":"Выберите окончание","phrase":"Ты чита__ каждый день.","options":["ешь","ишь","ет"],"answer":"ешь","explanation":"Читать — I спряжение: ты читаешь."},
    {"id":"pr-p2","prompt":"Выберите форму","phrase":"Мы говор__ по-русски.","options":["ем","им","ите"],"answer":"им","explanation":"Говорить — II спряжение: мы говорим."},
    {"id":"pr-p3","prompt":"Найдите правильную форму","phrase":"Я писать → ?","options":["писаю","пишу","писю"],"answer":"пишу","explanation":"В корне происходит чередование с → ш."}
  ]$json$::jsonb,
  $json$[
    {"id":"pr-g1","prompt":"Запустите двигатель","phrase":"Он работа__ дома.","options":["ет","ит","ют"],"answer":"ет","explanation":"Работать — I спряжение."},
    {"id":"pr-g2","prompt":"Продолжите путь","phrase":"Они вид__ море.","options":["ят","ют","ет"],"answer":"ят","explanation":"Видеть — исключение II спряжения: видят."},
    {"id":"pr-g3","prompt":"Выберите форму","phrase":"Ты люб__ музыку?","options":["ешь","ишь","ит"],"answer":"ишь","explanation":"Любить — II спряжение."},
    {"id":"pr-g4","prompt":"Обойдите ловушку","phrase":"Мы хотеть → ?","options":["хотим","хочем","хотем"],"answer":"хотим","explanation":"Хотеть спрягается особо: я хочу, мы хотим."}
  ]$json$::jsonb
),
(
  'grammar_past_future', 'proshedshee-i-budushchee', 'Прошедшее и будущее',
  'Как говорить о завершённых и будущих действиях', 'A1–A2', '⌛', 3, 'published',
  $json$[
    {"title":"Прошедшее время","text":"Обычно убираем -ть и добавляем -л. Форма зависит от рода и числа, но не от лица.","examples":["он читал · она читала · оно работало · они читали","я был / я была"],"note":"Идти → шёл, шла, шло, шли; мочь → мог, могла."},
    {"title":"Сложное будущее","text":"У глаголов несовершенного вида используем буду + инфинитив.","examples":["Я буду читать. · Мы будем работать."],"note":"После буду инфинитив не изменяется: буду читать, а не буду читаю."},
    {"title":"Простое будущее","text":"У совершенного вида форма похожа на настоящее, но обозначает результат в будущем.","examples":["Я прочитаю книгу. · Они сделают работу."],"note":"У совершенного вида настоящего времени нет."}
  ]$json$::jsonb,
  $json$[
    {"id":"pf-p1","prompt":"Согласуйте форму","phrase":"Анна вчера работа__.","options":["л","ла","ли"],"answer":"ла","explanation":"Анна — женский род: работала."},
    {"id":"pf-p2","prompt":"Выберите будущее","phrase":"Завтра я ___ читать.","options":["буду","будет","прочитаю"],"answer":"буду","explanation":"Несовершенный вид: буду читать."},
    {"id":"pf-p3","prompt":"Выберите результат","phrase":"К вечеру я ___ книгу.","options":["буду читать","прочитаю","читаю"],"answer":"прочитаю","explanation":"Нужен завершённый результат к вечеру."}
  ]$json$::jsonb,
  $json$[
    {"id":"pf-g1","prompt":"Верните время","phrase":"Они вчера ___ в парк.","options":["шли","шёл","идут"],"answer":"шли","explanation":"Идти → они шли."},
    {"id":"pf-g2","prompt":"Откройте завтра","phrase":"Мы ___ работать весь день.","options":["будем","будут","сделаем"],"answer":"будем","explanation":"Мы будем работать."},
    {"id":"pf-g3","prompt":"Поймайте результат","phrase":"Я обязательно ___ тебе.","options":["буду звонить","позвоню","звонил"],"answer":"позвоню","explanation":"Позвоню обещает конкретный результат."},
    {"id":"pf-g4","prompt":"Согласуйте","phrase":"Вчера я не ___ прийти. (муж.)","options":["мог","могла","могли"],"answer":"мог","explanation":"Мочь → мог; для женщины — могла."}
  ]$json$::jsonb
),
(
  'grammar_aspect', 'vidy-glagola', 'Виды глагола',
  'Процесс, повторяемость и результат: НСВ или СВ', 'A2', '◐', 4, 'published',
  $json$[
    {"title":"Несовершенный вид","text":"НСВ показывает процесс, повторение, привычку или факт действия без акцента на результате. Отвечает на вопрос что делать?","examples":["Я читал два часа. · Я каждый день читаю.","Ты когда-нибудь читал эту книгу?"],"note":"Слова часто, обычно, долго, каждый день часто ведут к НСВ."},
    {"title":"Совершенный вид","text":"СВ показывает завершённый результат или одно последовательное действие. Отвечает на вопрос что сделать?","examples":["Я прочитал книгу. · Сначала поел, потом позвонил."],"note":"СВ не имеет настоящего времени: прочитаю — будущее."},
    {"title":"Пары","text":"Вид часто образуется приставкой или суффиксом, но форму лучше учить парой.","examples":["читать → прочитать · делать → сделать","покупать → купить · брать → взять"],"note":"Приставка иногда меняет не только вид, но и значение: писать → подписать."}
  ]$json$::jsonb,
  $json$[
    {"id":"as-p1","prompt":"Процесс или результат?","phrase":"Я ___ отчёт и отправил его.","options":["писал","написал","пишу"],"answer":"написал","explanation":"Отчёт завершён и отправлен."},
    {"id":"as-p2","prompt":"Выберите привычку","phrase":"По утрам она ___ кофе.","options":["выпила","пила","попила"],"answer":"пила","explanation":"Регулярное действие требует НСВ."},
    {"id":"as-p3","prompt":"Найдите видовую пару","phrase":"брать → ?","options":["забрать","взять","брал"],"answer":"взять","explanation":"Брать / взять — видовая пара."}
  ]$json$::jsonb,
  $json$[
    {"id":"as-g1","prompt":"Завершите миссию","phrase":"Наконец мы ___ задачу.","options":["решали","решили","решаем"],"answer":"решили","explanation":"Наконец подчёркивает результат."},
    {"id":"as-g2","prompt":"Сохраните процесс","phrase":"Весь вечер я ___ фильм.","options":["посмотрел","смотрел","увидел"],"answer":"смотрел","explanation":"Длительность весь вечер — НСВ."},
    {"id":"as-g3","prompt":"Выберите факт опыта","phrase":"Ты когда-нибудь ___ борщ?","options":["готовил","приготовил","готовишь"],"answer":"готовил","explanation":"Вопрос о самом факте опыта — НСВ."},
    {"id":"as-g4","prompt":"Поймайте результат","phrase":"Подожди, я сейчас ___ письмо.","options":["писал","допишу","пишу всегда"],"answer":"допишу","explanation":"Допишу — закончу начатое."}
  ]$json$::jsonb
),
(
  'grammar_pronouns_modals', 'mestoimeniya-hotet-moch', 'Местоимения, хотеть и мочь',
  'Личные формы и два важнейших модальных глагола', 'A1–A2', '◎', 5, 'published',
  $json$[
    {"title":"Личные местоимения","text":"Форма местоимения меняется по падежу. После большинства предлогов у он, она, они появляется н-.","examples":["я → меня → мне → мной","он → его / у него · она → её / к ней · они → их / с ними"],"note":"После благодаря, согласно, вопреки начальное н- не добавляется: благодаря ему."},
    {"title":"Хотеть","text":"Хотеть спрягается смешанно.","examples":["я хочу · ты хочешь · он хочет","мы хотим · вы хотите · они хотят"],"note":"После хотеть ставим инфинитив: хочу учиться."},
    {"title":"Мочь","text":"Мочь выражает возможность или способность.","examples":["могу, можешь, может, можем, можете, могут","Я могу помочь. · Здесь можно работать."],"note":"Мочь относится к человеку; можно описывает общую возможность."}
  ]$json$::jsonb,
  $json$[
    {"id":"pm-p1","prompt":"Выберите форму","phrase":"Мы ___ говорить по-русски.","options":["можем","могут","можете"],"answer":"можем","explanation":"Мы можем."},
    {"id":"pm-p2","prompt":"Поставьте после предлога","phrase":"Я говорю о ___. (он)","options":["ём","нём","его"],"answer":"нём","explanation":"После о: о нём."},
    {"id":"pm-p3","prompt":"Выберите форму","phrase":"Они ___ домой.","options":["хочет","хотят","хочут"],"answer":"хотят","explanation":"Они хотят."}
  ]$json$::jsonb,
  $json$[
    {"id":"pm-g1","prompt":"Найдите адресата","phrase":"Позвони ___. (я)","options":["меня","мне","мной"],"answer":"мне","explanation":"Звонить кому? — мне."},
    {"id":"pm-g2","prompt":"Выберите возможность","phrase":"Здесь ___ припарковаться?","options":["можно","может","могу"],"answer":"можно","explanation":"Общая возможность выражается словом можно."},
    {"id":"pm-g3","prompt":"Соберите желание","phrase":"Ты ___ отдохнуть?","options":["хочешь","хотишь","хочет"],"answer":"хочешь","explanation":"Ты хочешь."},
    {"id":"pm-g4","prompt":"Пройдите предлог","phrase":"Я иду с ___. (они)","options":["их","ними","им"],"answer":"ними","explanation":"Творительный после с: с ними."}
  ]$json$::jsonb
),
(
  'grammar_prepositional', 'predlozhnyy-padezh', 'Предложный падеж',
  'Где? О ком? О чём? Окончания после в, на, о и при', 'A1–A2', '⌖', 6, 'published',
  $json$[
    {"title":"Главный сигнал","text":"Предложный падеж употребляется только с предлогом. Для места отвечаем где?, для темы разговора — о ком? о чём?","examples":["в школе · на работе · о книге · при Петре I"],"note":"Куда? требует винительного: в школу. Где? — предложного: в школе."},
    {"title":"Окончания","text":"Обычно ставим -е. Слова на -ия/-ие и существительные женского рода на -ь получают -и.","examples":["город → в городе · музей → в музее","Россия → в России · здание → в здании · площадь → на площади"],"note":"Во множественном числе: -ах/-ях — в городах, о друзьях."},
    {"title":"Особое -у́","text":"Небольшая группа слов места имеет ударное окончание -у́.","examples":["в лесу́ · в саду́ · на полу́ · в шкафу́","на мосту́ · в аэропорту́ · на берегу́"],"note":"Но о лесе, о саде, об аэропорте — при значении темы возвращается -е."}
  ]$json$::jsonb,
  $json$[
    {"id":"pp-p1","prompt":"Где?","phrase":"Мы живём в ___. (Россия)","options":["Россию","России","Россия"],"answer":"России","explanation":"Слова на -ия получают -и."},
    {"id":"pp-p2","prompt":"Куда или где?","phrase":"Дети сейчас в ___. (школа)","options":["школу","школе","школы"],"answer":"школе","explanation":"Где? — в школе."},
    {"id":"pp-p3","prompt":"Особая форма места","phrase":"Грибы растут в ___. (лес)","options":["лесе","лесу","лесом"],"answer":"лесу","explanation":"При значении места: в лесу́."}
  ]$json$::jsonb,
  $json$[
    {"id":"pp-g1","prompt":"Найдите место","phrase":"Книга лежит на ___. (стол)","options":["столе","стол","столу"],"answer":"столе","explanation":"На чём? На столе."},
    {"id":"pp-g2","prompt":"Выберите тему","phrase":"Мы говорили о ___. (путешествие)","options":["путешествии","путешествие","путешествию"],"answer":"путешествии","explanation":"-ие → -ии: о путешествии."},
    {"id":"pp-g3","prompt":"Пройдите площадь","phrase":"Встречаемся на ___. (площадь)","options":["площаде","площади","площадью"],"answer":"площади","explanation":"Женский род на -ь получает -и."},
    {"id":"pp-g4","prompt":"Различите направление","phrase":"После уроков я иду в ___. (библиотека)","options":["библиотеке","библиотеку","библиотеки"],"answer":"библиотеку","explanation":"Куда? — винительный: в библиотеку."}
  ]$json$::jsonb
),
(
  'grammar_dative', 'datelnyy-padezh', 'Дательный падеж',
  'Кому? Чему? Адресат, состояние, возраст и направление к человеку', 'A2', '→', 7, 'published',
  $json$[
    {"title":"Окончания","text":"Мужской и средний род: -у/-ю; женский на -а/-я: -е; -ия и женский род на -ь: -и. Во множественном числе: -ам/-ям.","examples":["брату · учителю · окну","маме · Марии · матери · детям"],"note":"У слов мать и дочь меняется основа: матери, дочери."},
    {"title":"Основные значения","text":"Дательный обозначает адресата, возраст, состояние и лицо в безличной конструкции.","examples":["Я дал другу книгу. · Мне 25 лет.","Мне холодно. · Ей нужно работать. · Нам нравится музыка."],"note":"По-русски не Я 25 лет, а Мне 25 лет."},
    {"title":"Предлоги и глаголы","text":"К + дательный ведёт к человеку или ориентиру; по имеет несколько значений. Дательного требуют помогать, звонить, верить, мешать, советовать, объяснять.","examples":["к врачу · ко мне · к вечеру","по улице · по телефону · скучаю по тебе"],"note":"К человеку — к врачу; в место — в больницу."}
  ]$json$::jsonb,
  $json$[
    {"id":"dt-p1","prompt":"Кому?","phrase":"Я звоню ___. (друг)","options":["друга","другу","другом"],"answer":"другу","explanation":"Звонить кому? — другу."},
    {"id":"dt-p2","prompt":"Выразите возраст","phrase":"___ двадцать пять лет.","options":["Я","Мне","Меня"],"answer":"Мне","explanation":"Возраст выражается дательным: мне 25 лет."},
    {"id":"dt-p3","prompt":"Выберите направление","phrase":"Завтра я иду к ___. (врач)","options":["врача","врачу","врачом"],"answer":"врачу","explanation":"К + дательный: к врачу."}
  ]$json$::jsonb,
  $json$[
    {"id":"dt-g1","prompt":"Передайте помощь","phrase":"Она помогает ___. (мать)","options":["матери","мать","матерью"],"answer":"матери","explanation":"Мать → матери."},
    {"id":"dt-g2","prompt":"Опишите состояние","phrase":"___ было интересно. (они)","options":["Их","Им","Ними"],"answer":"Им","explanation":"Кому было интересно? — им."},
