(
  'grammar_instrumental', 'tvoritelnyy-padezh', 'Творительный падеж',
  'Кем? Чем? Совместность, инструмент, профессия и предлоги места', 'A2', '⚒', 10, 'published',
  $json$[
    {"title":"Окончания","text":"Мужской и средний род: -ом/-ем; женский: -ой/-ей, возможен книжный вариант -ою/-ею. Множественное число: -ами/-ями.","examples":["столом · музеем · морем","мамой · неделей · друзьями"],"note":"Мать → матерью, дочь → дочерью, время → временем."},
    {"title":"С кем и чем","text":"Творительный обозначает совместность и инструмент.","examples":["с другом · с семьёй","писать ручкой · резать ножом · ехать автобусом"],"note":"С + творительный = вместе; с + родительный = откуда: с другом / с работы."},
    {"title":"Роль и место","text":"После быть, стать, работать в значении профессии часто нужен творительный. Его требуют и предлоги над, под, перед, за, между, рядом с.","examples":["Он стал врачом. · Она работает дизайнером.","под столом · перед домом · между зданиями"],"note":"В настоящем времени возможна конструкция Он врач без творительного."}
  ]$json$::jsonb,
  $json$[
