    {"id":"tv-p2","prompt":"Чем?","phrase":"Она пишет ___. (ручка)","options":["ручкой","ручку","ручке"],"answer":"ручкой","explanation":"Инструмент ставится в творительном."},
    {"id":"tv-p3","prompt":"Кем стал?","phrase":"Он стал ___. (врач)","options":["врач","врача","врачом"],"answer":"врачом","explanation":"Стать кем? — врачом."}
  ]$json$::jsonb,
