    {"id":"tv-g4","prompt":"Различите значение","phrase":"Я вернулся с ___. (работа)","options":["работой","работы","работу"],"answer":"работы","explanation":"Откуда? С работы — родительный, не творительный."}
  ]$json$::jsonb
