  $json$[
    {"title":"Прилагательное","text":"Прилагательное отвечает какой? какая? какое? какие? и согласуется с существительным в роде, числе и падеже.","examples":["новый дом · новая улица · новое место · новые дома","в новом доме · к новой улице"],"note":"Окончание выбираем по существительному, а не по ближайшему слову."},
    {"title":"Наречие","text":"Наречие отвечает как? и обычно не изменяется. Часто образуется от прилагательного с помощью -о/-е.","examples":["быстрый поезд → поезд едет быстро","хорошая работа → работать хорошо"],"note":"Он хороший — прилагательное; он говорит хорошо — наречие."},
    {"title":"Степени сравнения","text":"Простая сравнительная форма часто получает -ее/-ей или меняет основу.","examples":["быстрый → быстрее · красивый → красивее","хороший → лучше · плохой → хуже · большой → больше"],"note":"После сравнительной формы: чем + именительный или родительный без чем."}
  ]$json$::jsonb,
  $json$[
