    {"id":"aj-p2","prompt":"Как?","phrase":"Она говорит очень ___.","options":["тихая","тихо","тихий"],"answer":"тихо","explanation":"Говорит как? — тихо."},
    {"id":"aj-p3","prompt":"Сравните","phrase":"Этот путь ___ того.","options":["короткий","короче","коротко"],"answer":"короче","explanation":"Нужна сравнительная форма: короче."}
