    {"id":"aj-g2","prompt":"Выберите наречие","phrase":"Он ___ ответил на вопрос.","options":["правильный","правильно","правильнее"],"answer":"правильно","explanation":"Ответил как? — правильно."},
    {"id":"aj-g3","prompt":"Найдите особую форму","phrase":"Хорошо → сравнительная степень","options":["хорошее","лучше","более хорошо"],"answer":"лучше","explanation":"Особая форма — лучше."},
    {"id":"aj-g4","prompt":"Согласуйте число","phrase":"На столе лежат ___ книги.","options":["новая","новые","новых"],"answer":"новые","explanation":"Именительный множественного: новые книги."}
  ]$json$::jsonb
