  $json$[
    {"title":"После чисел","text":"После один существительное согласуется в числе и роде. После 2–4 обычно нужен родительный единственного, после 5–20 и 0 — родительный множественного.","examples":["один стол · одна книга · одно окно","два стола · три книги · четыре окна","пять столов · десять книг · ноль ошибок"],"note":"11–14 всегда относятся к группе 5+: одиннадцать книг, даже если последняя цифра 1–4."},
    {"title":"Составные числа","text":"Смотрим на последнюю значимую часть, кроме 11–14.","examples":["двадцать один день · двадцать две минуты","двадцать пять дней · сто один человек"],"note":"21 год, но 11 лет; 22 года, но 12 лет."},
    {"title":"Глаголы на -ся","text":"-ся/-сь может показывать действие на себя, взаимность, состояние или страдательное значение. После согласной пишется -ся, после гласной — -сь.","examples":["умываться · встречаться · улыбаться","дом строится · я учусь · он боится"],"note":"Не каждый глагол без -ся существует с тем же значением: бояться нужно учить целиком."}
  ]$json$::jsonb,
  $json$[
    {"id":"nr-p1","prompt":"Выберите форму","phrase":"У меня двадцать два ___. (год)","options":["год","года","лет"],"answer":"года","explanation":"22 оканчивается на 2, но не на 12: два года."},
    {"id":"nr-p2","prompt":"Не попадитесь на 11","phrase":"Прошло одиннадцать ___. (день)","options":["день","дня","дней"],"answer":"дней","explanation":"11 требует родительного множественного."},
    {"id":"nr-p3","prompt":"Выберите постфикс","phrase":"Она улыба__.","options":["ется","етсь","ится"],"answer":"ется","explanation":"Улыбаться → она улыбается."}
