    {"id":"nr-g2","prompt":"Обойдите 14","phrase":"Мне двадцать четыре года, а брату четырнадцать ___.","options":["год","года","лет"],"answer":"лет","explanation":"14 относится к исключительной группе 11–14."},
    {"id":"nr-g3","prompt":"Найдите взаимность","phrase":"Друзья часто ___.","options":["встречают","встречаются","встречает"],"answer":"встречаются","explanation":"Встречаются друг с другом — взаимное действие."},
    {"id":"nr-g4","prompt":"Выберите форму","phrase":"Я учу__ русскому языку.","options":["ся","сь","юсь"],"answer":"сь","explanation":"После гласной: учусь."}
